class Solution:
    def solve(self, m, n, nums,dp):
        if m == len(nums) -1:
            return nums[m][n]
        if dp[m][n] != -1:
            return dp[m][n]
        down = nums[m][n] + self.solve(m+1,n,nums, dp)
        digonal =nums[m][n] + self.solve(m+1,n+1,nums, dp)
        dp[m][n] = min(down,digonal)
        return dp[m][n]

